    print(f"Output {i}: '{out}'")
    print(f"Difference: ", end="")
    if inp == out:
        print("None")
    else:
        diff_positions = []
        for j, (char_in, char_out) in enumerate(zip(inp, out)):
            if char_in != char_out:
                diff_positions.append((j, char_in, char_out))
        if diff_positions:
            for pos, char_in, char_out in diff_positions:
                print(f"pos{pos}:'{char_in}'->'{char_out}' ", end="")
        else:
            # Check if lengths differ
            if len(inp) != len(out):
                print(f"Length change: {len(inp)}->{len(out)}")
            else:
                print("Unknown difference")
    print("\n")

